#!/usr/bin/env bash
# Rilis 0082 ke PRODUKSI lewat /api/admin/db — satu statement per panggilan
# (endpoint membungkus transaksinya sendiri; statement berat bikin 502).
# Jalankan dari root repo SETELAH kode ter-deploy. Idempoten: aman diulang.
#
# Isi: kolom pengajar.matrix_blok + seed blok akhwat dari list koordinator.
# Nama tidak ditulis di sini, hanya id — peta nama→id ada di
# scripts/sql/0082-seed-matrix-blok-akhwat.sql (komentar per blok).
set -euo pipefail
db() { npm run -s db -- --confirm "$1"; }

# ---- DDL (kolom dan constraint dipisah: statement gabungan pernah bikin 502) ----
db "ALTER TABLE pengajar ADD COLUMN IF NOT EXISTS matrix_blok text"
db "ALTER TABLE pengajar DROP CONSTRAINT IF EXISTS pengajar_matrix_blok_check"
db "ALTER TABLE pengajar ADD CONSTRAINT pengajar_matrix_blok_check CHECK (matrix_blok IS NULL OR matrix_blok IN ('takhassus','koordinator','tahfizh','talaqqi','maahir6'))"

